export function matchBusinessToCategory(
  sector: string | null,
  keywords: string | null,
): MarketplaceCategory | null {
  if (!sector && !keywords) return null;

  const searchText = [sector, keywords].filter(Boolean).join(" ").toLowerCase();

  let bestMatch: MarketplaceCategory | null = null;
  let bestScore = 0;

  for (const [category, categoryKeywords] of Object.entries(
    CATEGORY_KEYWORDS,
  )) {
    let score = 0;
    for (const keyword of categoryKeywords) {
      if (searchText.includes(keyword.toLowerCase())) {
        score++;
      }
    }
    if (score > bestScore) {
      bestScore = score;
      bestMatch = category as MarketplaceCategory;
    }
  }

  return bestScore > 0 ? bestMatch : null;
}
